#[derive(Live, LiveHook)]
pub struct App {
    #[live]
    pub ui: WidgetRef,
    #[rust]
    pub form: FormMain,
    #[rust(true)]
    pub initial_sync: bool,
    #[rust]
    pub grid1_opened: bool,
    #[rust]
    pub crawrad_pointer: CrawradPointerRouter,
}

impl App {
    pub fn sync_ui(&mut self, cx: &mut Cx) {
        self.ui.widget(id!(grid1)).set_visible(cx, self.form.grid1.visible);
        crawrad_runtime_makepad::enabled::apply(cx, &self.ui, id!(grid1), self.form.grid1.enabled);
        if !self.grid1_opened {
            self.grid1_opened = true;
            let (source, columns) = match datagrid_sql::SqlSource::open_sqlite_query(crawrad_runtime::db_url::resolve_sqlite_url(&self.form.conn1.url, env!("CARGO_MANIFEST_DIR")), &self.form.dst1.sql) {
                Ok(source) => {
                    let columns = crawrad_runtime::grid::GridColumn::from_schema_and_design(datagrid::RowSource::schema(&source), &[]);
                    (std::sync::Arc::new(source) as std::sync::Arc<dyn datagrid::RowSource>, columns)
                }
                Err(e) => (
                    std::sync::Arc::new(crawrad_runtime::grid::UnavailableSource::from_error(&e)) as std::sync::Arc<dyn datagrid::RowSource>,
                    Vec::new(),
                ),
            };
            crawrad_runtime_makepad::CrawradDataGridWidgetRefExt::crawrad_data_grid(&self.ui, id!(grid1)).set_source(cx, source, columns);
            crawrad_runtime_makepad::CrawradDataGridWidgetRefExt::crawrad_data_grid(&self.ui, id!(grid1)).set_row_height(self.form.grid1.default_row_height as f64);
            crawrad_runtime_makepad::CrawradDataGridWidgetRefExt::crawrad_data_grid(&self.ui, id!(grid1)).set_group_bar(cx, self.form.grid1.group_bar);
        }
        crawrad_runtime_makepad::dialogs::sync_message_dialog(cx, &self.ui.view(id!(crawrad_message_dialog)));
        self.ui.redraw(cx);
    }
}

